// Analyze the 7-day Open-Meteo forecast and derive a shipping/inventory risk profile.
const weather = $input.first().json;
const config = $('Agent Config').first().json;
const daily = weather.daily || {};
const days = (daily.time || []).map((date, i) => ({
  date,
  tempMax: daily.temperature_2m_max?.[i],
  tempMin: daily.temperature_2m_min?.[i],
  precipitationSum: daily.precipitation_sum?.[i],
  precipitationProbability: daily.precipitation_probability_max?.[i],
  windSpeedMax: daily.windspeed_10m_max?.[i],
  weatherCode: daily.weathercode?.[i]
}));

// Weather codes considered severe per WMO code table used by Open-Meteo.
const SEVERE_CODES = new Set([65, 67, 75, 82, 86, 95, 96, 99]);
const MODERATE_CODES = new Set([55, 63, 73, 81, 85]);

const reasons = [];
let score = 0; // higher = riskier

for (const d of days) {
  if (d.precipitationSum >= 40 || d.precipitationProbability >= 80) {
    score += 3;
    reasons.push(`Heavy rain expected ${d.date} (${d.precipitationSum}mm, ${d.precipitationProbability}% chance)`);
  } else if (d.precipitationSum >= 15) {
    score += 1;
    reasons.push(`Moderate rain expected ${d.date} (${d.precipitationSum}mm)`);
  }
  if (d.windSpeedMax >= 60) {
    score += 3;
    reasons.push(`High winds expected ${d.date} (${d.windSpeedMax} km/h)`);
  } else if (d.windSpeedMax >= 40) {
    score += 1;
    reasons.push(`Elevated winds expected ${d.date} (${d.windSpeedMax} km/h)`);
  }
  if (d.tempMax >= 42 || d.tempMin <= 0) {
    score += 2;
    reasons.push(`Extreme temperature expected ${d.date} (min ${d.tempMin}C / max ${d.tempMax}C)`);
  }
  if (SEVERE_CODES.has(d.weatherCode)) {
    score += 3;
    reasons.push(`Severe weather (code ${d.weatherCode}) forecast ${d.date}`);
  } else if (MODERATE_CODES.has(d.weatherCode)) {
    score += 1;
  }
}

let riskLevel = 'NONE';
if (score >= 8) riskLevel = 'SEVERE';
else if (score >= 5) riskLevel = 'HIGH';
else if (score >= 2) riskLevel = 'MODERATE';
else if (score >= 1) riskLevel = 'LOW';

const expediteRecommended = riskLevel === 'HIGH' || riskLevel === 'SEVERE';

return [{
  json: {
    location_name: config.location_name,
    latitude: config.latitude,
    longitude: config.longitude,
    supabase_table: config.supabase_table,
    low_stock_multiplier: config.low_stock_multiplier,
    alert_email: config.alert_email,
    forecast_days: days,
    risk_score: score,
    risk_level: riskLevel,
    risk_reasons: reasons,
    expedite_recommended: expediteRecommended,
    checked_at: new Date().toISOString()
  }
}];

// Combine each inventory row with the weather risk analysis to decide shipping/reorder actions.
const weather = $('Analyze Weather Risk').first().json;
const items = $input.all().map(i => i.json);

const results = items.map(item => {
  const reorderThreshold = Number(item.reorder_threshold ?? 0);
  const stockQty = Number(item.stock_quantity ?? 0);
  const lowStockCutoff = reorderThreshold * Number(weather.low_stock_multiplier ?? 1.5);
  const isLowStock = stockQty <= lowStockCutoff;
  const weatherIsRisky = weather.risk_level === 'HIGH' || weather.risk_level === 'SEVERE';

  const expediteShipping = weatherIsRisky && isLowStock;
  const priorityLevel = expediteShipping
    ? weather.risk_level
    : (isLowStock ? 'LOW_STOCK_ONLY' : 'NORMAL');

  const recommendedReorderQty = isLowStock
    ? Math.max(reorderThreshold * 2 - stockQty, 0)
    : 0;

  const actionNeeded = expediteShipping || isLowStock;

  return {
    json: {
      id: item.id,
      sku: item.sku,
      item_name: item.item_name,
      location_name: item.location_name,
      stock_quantity: stockQty,
      reorder_threshold: reorderThreshold,
      is_low_stock: isLowStock,
      weather_risk_level: weather.risk_level,
      weather_risk_reasons: weather.risk_reasons.join('; '),
      expedite_shipping: expediteShipping,
      priority_level: priorityLevel,
      recommended_reorder_qty: recommendedReorderQty,
      action_needed: actionNeeded,
      last_weather_check: weather.checked_at
    }
  };
});

return results;

// Build a single plain-text/HTML report summarizing weather risk and inventory actions.
const allItems = $('Compute Inventory Actions').all().map(i => i.json);
const weather = $('Analyze Weather Risk').first().json;
const flagged = allItems.filter(i => i.action_needed);

const lines = [];
lines.push(`<h2>Smart Inventory Weather Report — ${weather.location_name}</h2>`);
lines.push(`<p><b>Checked at:</b> ${weather.checked_at}</p>`);
lines.push(`<p><b>Weather risk level (next 7 days):</b> ${weather.risk_level} (score ${weather.risk_score})</p>`);

if (weather.risk_reasons.length) {
  lines.push('<p><b>Reasons:</b></p><ul>' + weather.risk_reasons.map(r => `<li>${r}</li>`).join('') + '</ul>');
} else {
  lines.push('<p>No significant weather risks detected.</p>');
}

if (flagged.length) {
  lines.push(`<p><b>${flagged.length} item(s) need action:</b></p>`);
  lines.push('<table border="1" cellpadding="6" cellspacing="0"><tr><th>SKU</th><th>Item</th><th>Stock</th><th>Priority</th><th>Expedite Shipping</th><th>Recommended Reorder Qty</th></tr>');
  for (const item of flagged) {
    lines.push(`<tr><td>${item.sku}</td><td>${item.item_name}</td><td>${item.stock_quantity}</td><td>${item.priority_level}</td><td>${item.expedite_shipping ? 'YES' : 'no'}</td><td>${item.recommended_reorder_qty}</td></tr>`);
  }
  lines.push('</table>');
} else {
  lines.push('<p>No inventory items currently need reorder or expedited shipping.</p>');
}

return [{
  json: {
    alert_email: weather.alert_email,
    location_name: weather.location_name,
    subject: `Smart Inventory Report — ${weather.location_name} — ${weather.risk_level} risk (${flagged.length} item(s) flagged)`,
    report_html: lines.join('\n'),
    flagged_count: flagged.length
  }
}];
